-- ===========================================================================
-- Warlock: Soulstone direct-cast, and Soul Shards stack to 32
-- ===========================================================================
--
-- 1. Soul Shards (item 6265) stack to 32.
--    item_template.maxcount is ALREADY 32, so the core's CanStoreNewItem
--    already refuses shard #33 on every creation path.  Only `stackable`
--    needs raising, so 32 shards occupy one bag slot instead of 32.
--    NOTE: `stackable` is sent in the item query response and cached
--    client-side, so existing characters may need a cache clear to see it.
--
-- 2. Soulstone is cast directly on a friendly target -- no intermediate item.
--    Each "Create Soulstone" rank changes from SPELL_EFFECT_CREATE_ITEM (24)
--    to SPELL_EFFECT_TRIGGER_SPELL (64) pointing at the matching
--    "Soulstone Resurrection" rank, which is ALREADY a friendly-target aura.
--
--    The on-death flow needs no changes: Player::GetResurrectionSpellId()
--    scans the dying player's SPELL_AURA_DUMMY list for
--    SpellVisual[0] == 99 && SpellIconID == 92 and maps the aura to the
--    matching "Use Soulstone" self-res spell.  It never checks who cast it
--    or whether an item ever existed.  So spells 20707/20762-5/27239/47883
--    and 3026/20758-61/27240/47882 are deliberately left untouched.
--
--    Rank pairing (Create -> Resurrection aura -> Use Soulstone):
--        693   -> 20707 -> 3026
--        20752 -> 20762 -> 20758
--        20755 -> 20763 -> 20759
--        20756 -> 20764 -> 20760
--        20757 -> 20765 -> 20761
--        27238 -> 27239 -> 27240
--        47884 -> 47883 -> 47882
--
--    RecoveryTime 900000 (15 min) replaces the cooldown that used to live on
--    the Soulstone *item*; without it the spell is infinitely recastable.
--    Reagent1 = 6265 is kept -- casting a Soulstone still costs a shard.
-- ===========================================================================

UPDATE `item_template` SET `stackable` = 32 WHERE `entry` = 6265;



